/** How long an old name keeps answering, in days. */
export const RENAME_DAYS = 30;

/** What an old name says while it still answers (the agent rename's words, SDLC plan A3). */
export function renamedNotice(oldName: string, newName: string, day: string): string {
  return `${oldName} was renamed to ${newName}. This name stops working on ${day}; use ${newName}.`;
}

/** What an old name says once its window has closed. */
export function renamedStopped(oldName: string, newName: string, day: string): string {
  return `${oldName} was renamed to ${newName} and stopped working on ${day}. Use ${newName}.`;
}

/** Whether a window that closes on `day` (YYYY-MM-DD, UTC) has closed. */
export function renameClosed(day: string, now: number = Date.now()): boolean {
  return now >= Date.parse(`${day}T00:00:00Z`);
}

