  against?: string[];
  /** Only this kind. */
  kind?: "dependency" | "technical";
  /** active (still owed: open or acknowledged), all, or one state. */
  state?: "active" | "all" | "open" | "acknowledged" | "resolved" | "overridden" | "dropped";
  /** Only items owed to this owner. */
  owed_to?: string;
  /** Only items that hold back this act. The deployment manager asks this before promote, rollback and decommission. */
  blocks?: "update" | "promote" | "rollback" | "decommission";
