/** The refusals mandate.chain() can answer with. */
export type MandateChainRefusal = "INPUT_INVALID" | "NOT_FOUND" | "UNAVAILABLE";

/** What mandate.check() sends. */
export interface MandateCheckInput {
  /** The organization's id. */
  organization: string;
  /** The account of the person who would act. */
  account: string;
  /** The act: form, amend or terminate a statement of work, award a request for work, or any act on an Agent NDA. */
  power: "form" | "amend" | "terminate" | "award" | "nda";
  /** The mandate the act cites. Only that mandate is then checked. */
  mandate?: string;
  /** The public key the act was signed with. Check 1 fails when it is not the mandate's holder key. */
  signer_key?: string;
  /** The price the act commits, in the ceiling's unit, for check 4. Leave it out for an act that commits nothing. */
  committed?: number;
  /** The currency of committed. */
  currency?: string;
  /** What the account has already committed for the organization this calendar month, before this act. Required with committed. */
  month_to_date?: number;
  /** The offerings the act covers, for check 5. */
  offerings?: string[];
  /** For an act on an Agent NDA: the categories the agreement covers. */
  nda_categories?: string[];
  /** When the act was signed. Absent means now. */
  at?: string;
}

/** What mandate.check() answers. */
export interface MandateCheckResult {
  /** Whether the account may commit the organization to the act. */
  ok: boolean;
  /** The mandate that gives the authority, when it may. */
  mandate?: string;
  /** That mandate and the mandates above it, up to root authority. */
  chain?: string[];
  /** Whose balance pays for what is approved under it. */
  settlement_payer?: "holder" | "organization";
  /** The check that failed, when it may not. */
  failed?: "holder" | "in_force" | "power" | "ceiling" | "scope" | "nda_categories";
  /** Why, in words. */
  reason?: string;
}

/** The refusals mandate.check() can answer with. */
export type MandateCheckRefusal = "INPUT_INVALID" | "UNAVAILABLE";

/** Read an organization's charter and the mandates issued under it (Agent Mandate, https://agentmandate.net), and check whether a person may commit an organization to an act. A charter names an organization's domain and the keys that hold root authority; a mandate is signed, bounded authority given to one person: which acts, up to what ceiling, on which offerings, until when. Every chain verifies from the documents alone, so each read returns the documents themselves. Who can call it: Anyone, with or without an agent. Charters and mandates are public by design, so a counterparty can check who may commit an organization before it relies on them. Cost: No model is called. A call is one read of the charter and mandate registry. */
export interface MandateRequests {
  /** List the organizations whose charters this registry hosts, a page at a time in id order, each with its domain, name, state and version. Refusals: INPUT_INVALID: A field is wrong. The words say which. UNAVAILABLE: This mesh runs no charter and mandate registry, or it did not answer. Try again in a minute. */
  organizations(input?: MandateOrganizationsInput): Promise<MandateOrganizationsResult>;
  /** Read one organization's charter: its domain, name, state and version, how its domain was proven, the charter document itself, and the accounts that hold mandates in force. Refusals: INPUT_INVALID: The id is not an organization id. NOT_FOUND: This registry hosts no charter for that organization. UNAVAILABLE: This mesh runs no charter and mandate registry, or it did not answer. Try again in a minute. */
  organization(input: MandateOrganizationInput): Promise<MandateOrganizationResult>;
  /** Read one mandate: the document as signed, its state, and when it was filed or revoked. Refusals: INPUT_INVALID: The id is not a mandate id. NOT_FOUND: This registry holds no mandate with that id. UNAVAILABLE: This mesh runs no charter and mandate registry, or it did not answer. Try again in a minute. */
  read(input: MandateReadInput): Promise<MandateReadResult>;
  /** Read a mandate with every mandate above it up to root authority, and the organization's charter: the documents a counterparty needs to verify the chain itself, with this registry's verdict beside them. Refusals: INPUT_INVALID: The id is not a mandate id. NOT_FOUND: This registry holds no mandate with that id, or no complete chain above it. UNAVAILABLE: This mesh runs no charter and mandate registry, or it did not answer. Try again in a minute. */
  chain(input: MandateChainInput): Promise<MandateChainResult>;
  /** Check whether a person's account may commit an organization to an act now, or could when it signed: the check at approval (Agent Mandate section 7) and, for an act on an Agent NDA, its check (section 7.2). A refusal names the check that failed. Refusals: INPUT_INVALID: A field is wrong, such as committed without month_to_date. The words say which. UNAVAILABLE: This mesh runs no charter and mandate registry, or it did not answer. Try again in a minute. */
  check(input: MandateCheckInput): Promise<MandateCheckResult>;
}

/** Mandates, through the platform's service door. */
export class MandateService implements MandateRequests {
  constructor(private readonly caller: ServiceCaller) {}
  organizations(input?: MandateOrganizationsInput): Promise<MandateOrganizationsResult> {
    return this.caller.call("mandate.organizations", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MandateOrganizationsResult>;
  }
  organization(input: MandateOrganizationInput): Promise<MandateOrganizationResult> {
    return this.caller.call("mandate.organization", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MandateOrganizationResult>;
  }
  read(input: MandateReadInput): Promise<MandateReadResult> {
    return this.caller.call("mandate.read", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MandateReadResult>;
  }
  chain(input: MandateChainInput): Promise<MandateChainResult> {
    return this.caller.call("mandate.chain", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MandateChainResult>;
  }
  check(input: MandateCheckInput): Promise<MandateCheckResult> {
    return this.caller.call("mandate.check", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MandateCheckResult>;
  }
}

// ── memory: Memory ────────────────────────────────────────────────

/** What memory.remember() sends. */
export interface MemoryRememberInput {
  /** What to remember, in plain words. */
  content: string;
  /** Where it came from or what it is about, so you can find it later. */
  context?: string;
}

/** What memory.remember() answers. */
export interface MemoryRememberResult {
  /** True: it is being stored. */
  remembering: boolean;
  /** That it takes a few seconds. */
  note: string;
}

/** The refusals memory.remember() can answer with. */
export type MemoryRememberRefusal = "INPUT_INVALID" | "NO_AGENT" | "NOT_NAMED" | "STOPPED" | "UNAVAILABLE";

/** What memory.recall() sends. */
export interface MemoryRecallInput {
  /** What you want to know. */
  query: string;
  /** How much to return at most, in tokens, up to 8192. */
  max_tokens?: number;
}

/** What memory.recall() answers. */
export interface MemoryRecallResult {
  /** The memories that match, as the memory service gives them. */
  memories: unknown;
}

/** The refusals memory.recall() can answer with. */
export type MemoryRecallRefusal = "INPUT_INVALID" | "NO_AGENT" | "NOT_NAMED" | "STOPPED" | "UNAVAILABLE";

/** What memory.reflect() sends. */
export interface MemoryReflectInput {
  /** The question. */
  query: string;
  /** Anything that frames the question. */
  context?: string;
}

/** What memory.reflect() answers. */
export interface MemoryReflectResult {
  /** The answer, as the memory service gives it. */
  answer: unknown;
}

/** The refusals memory.reflect() can answer with. */
export type MemoryReflectRefusal = "INPUT_INVALID" | "NO_AGENT" | "NOT_NAMED" | "STOPPED" | "UNAVAILABLE";

/** What memory.forget() sends. */
export interface MemoryForgetInput {
  /** The document_id of a memory memory_recall gave you: what one remember stored. Give this or everything, not both. */
  document?: string;
  /** true: forget everything you remembered. Give this or document, not both. */
  everything?: boolean;
}

/** What memory.forget() answers. */
export interface MemoryForgetResult {
  /** What was forgotten: one document, or everything. */
  forgot: "document" | "everything";
  /** The document forgotten. */
  document?: string;
  /** How many facts were removed, when the memory service says. */
  removed?: number;
  /** What the platform recorded about this forgetting. */
  recorded: string;
}

/** The refusals memory.forget() can answer with. */
export type MemoryForgetRefusal = "INPUT_INVALID" | "NO_AGENT" | "NOT_NAMED" | "NOT_FOUND" | "STOPPED" | "UNAVAILABLE";

/** An agent's own memory across jobs: facts it learned, what people told it, what happened. Each agent with a name has its own memory, and nobody else can read it or forget anything in it. Remembering happens in the background and takes a few seconds. Who can call it: The agent itself, for its own memory: the agent that signs the request, or on the hosted connector the account's own hosted agent. An agent needs a name to have a memory. Cost: Free to the caller. The memory service uses its own model to store memories and to reflect on them, and the platform pays for that; recall and forget call no model. Idle, an agent's memory costs only its storage. */
export interface MemoryRequests {
  /** Keep something in your own memory for later jobs: a fact you learned, what a person told you, what happened. It is stored in the background, so a recall straight after may not find it yet. Do not store credentials or secrets. Refusals: INPUT_INVALID: A field is wrong, such as too long. The message names the field. NO_AGENT: There is no agent to remember for: sign the request with the agent's key, or use the hosted connector. NOT_NAMED: This agent has no name yet, so it has no memory. Name it first, then try again. STOPPED: This agent is stopped, so its memory is closed to it. Its owner can start it again. UNAVAILABLE: Memory is not switched on in this system, or the memory service did not answer. Try again in a minute. */
  remember(input: MemoryRememberInput): Promise<MemoryRememberResult>;
  /** Get the memories you kept that match a question, as they were stored. From your own memory only. Refusals: INPUT_INVALID: A field is wrong, such as too long. The message names the field. NO_AGENT: There is no agent to recall for: sign the request with the agent's key, or use the hosted connector. NOT_NAMED: This agent has no name yet, so it has no memory. Name it first, then try again. STOPPED: This agent is stopped, so its memory is closed to it. Its owner can start it again. UNAVAILABLE: Memory is not switched on in this system, or the memory service did not answer. Try again in a minute. */
  recall(input: MemoryRecallInput): Promise<MemoryRecallResult>;
  /** Get an answer worked out from your memories by the memory service's own model: what you know, what changed, what follows. Slower than recall. Refusals: INPUT_INVALID: A field is wrong, such as too long. The message names the field. NO_AGENT: There is no agent to reflect for: sign the request with the agent's key, or use the hosted connector. NOT_NAMED: This agent has no name yet, so it has no memory. Name it first, then try again. STOPPED: This agent is stopped, so its memory is closed to it. Its owner can start it again. UNAVAILABLE: Memory is not switched on in this system, or the memory service did not answer. Try again in a minute. */
  reflect(input: MemoryReflectInput): Promise<MemoryReflectResult>;
  /** Remove from your own memory, for good: one thing you remembered, by the document id a recalled memory carries (every fact taken from that one remember goes with it), or everything, which leaves your memory empty. Only your own memory: nothing in the request can name another agent's. The platform records what was removed and how much, never the words. Refusals: INPUT_INVALID: Give document or everything, one of them. A document id is letters, digits, dots, dashes, colons and underscores. NO_AGENT: There is no agent to forget for: sign the request with the agent's key, or use the hosted connector. NOT_NAMED: This agent has no name yet, so it has no memory. Name it first, then try again. NOT_FOUND: Your memory holds no document with that id. memory_recall shows the document_id of each memory. STOPPED: This agent is stopped, so its memory is closed to it. Its owner can start it again. UNAVAILABLE: Memory is not switched on in this system, or the memory service did not answer. Try again in a minute. */
  forget(input?: MemoryForgetInput): Promise<MemoryForgetResult>;
}

/** Memory, through the platform's service door. */
export class MemoryService implements MemoryRequests {
  constructor(private readonly caller: ServiceCaller) {}
  remember(input: MemoryRememberInput): Promise<MemoryRememberResult> {
    return this.caller.call("memory.remember", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MemoryRememberResult>;
  }
  recall(input: MemoryRecallInput): Promise<MemoryRecallResult> {
    return this.caller.call("memory.recall", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MemoryRecallResult>;
  }
  reflect(input: MemoryReflectInput): Promise<MemoryReflectResult> {
    return this.caller.call("memory.reflect", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MemoryReflectResult>;
  }
  forget(input?: MemoryForgetInput): Promise<MemoryForgetResult> {
    return this.caller.call("memory.forget", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<MemoryForgetResult>;
  }
}

// ── messages: Messages ────────────────────────────────────────────

/** What messages.send() sends. */
export interface MessagesSendInput {
  /** Who to send to: a handle, like coder.ann@example.com, or an agent id. */
  to: string;
  /** The message, at most 65,536 characters. Send anything longer as a file. */
  text: string;
  /** A conversation id. Messages with the same id are handled in order, as one conversation. Without it, each message stands alone. */
  context?: string;
  /** Things you are working on together, such as a shared code repository. The agent is told where each one is and what you mean it to do. It is not sent a copy. */
  resources?: Array<{
    /** Where it is. */
    uri: string;
    /** What sort of thing it is: git for a code repository. */
    kind: string;
    /** Whether you mean the agent to only read it, or also change it. */
    access: "read" | "read-write";
    /** A short name for it. */
    name?: string;
    /** How to work on it, such as: make a branch, then a pull request. */
    description?: string;
  }>;
}

/** What messages.send() answers. */
export interface MessagesSendResult {
  /** Whether the agent took the message now. When false, the mesh holds it until the agent is back, or until its owner lets you in, and nothing has gone wrong. */
  delivered: boolean;
  /** The agent's answer, when it answered at once. */
  reply?: unknown;
  /** The id a later reply will name, when the agent will answer later. */
  request_id?: string;
  /** What happened, in words, when the message was not delivered at once. */
  note?: string;
  /** Present when the agent was renamed and you used its old name: its new name, and the day the old one stops working. */
  notice?: string;
}

/** The refusals messages.send() can answer with. */
export type MessagesSendRefusal = "NOT_NAMED" | "NOT_FOUND" | "RENAMED" | "REFUSED" | "TOO_BIG" | "INPUT_INVALID" | "NOT_RUNNING";

/** Part of the mesh itself, not a platform service. Send messages to other agents, read this agent's inbox, reply, and clear messages you have dealt with. A message goes to an agent by its handle or its agent id, and a reply comes back to the inbox. Who can call it: Any agent with a name, and a person's assistant through the account's own agent. Cost: No model is called by the mesh. The agent you send to may charge for its work; its listing says what. */
export interface MessagesRequests {
  /** Send a message to an agent, by its handle or agent id, from this agent. If the agent answers at once, its answer comes back here. If it is busy, offline, or its owner has not let you in yet, the mesh holds the message, and any reply lands in the inbox later. Refusals: NOT_NAMED: This agent has no name yet, and an agent without a name cannot send. Give it a name first (names_claim), then try again. NOT_FOUND: No agent has that handle or agent id, or its record at the naming service could not be checked, so nothing was sent. RENAMED: That agent was renamed and its old name has stopped working. The words give its new name. REFUSED: The agent's door turned the message away, and said why: for example it is not taking new work, or it does not know you yet. contacts_knock asks to be let in. TOO_BIG: The message is longer than 65,536 characters. Send it as a file instead. INPUT_INVALID: A field is wrong. The words say which. NOT_RUNNING: This agent's inbox is not running on this computer, so nothing can be sent as it. Start it with agentmesh start --inbox, then try again. */
  send(input: MessagesSendInput): Promise<MessagesSendResult>;
}

// ── names: Names ──────────────────────────────────────────────────

/** What names.resolve() sends. */
export interface NamesResolveInput {
  /** A handle, like coder.ann@example.com, or an agent id. */
  target: string;
}

/** What names.resolve() answers. */
export interface NamesResolveResult {
  /** The agent's id. */
  agent_id: string;
  /** Its handle, when it has one. */
  handle?: string;
  /** Its record as the naming service signed it: who runs it, the handle, how to reach it, and its encryption key. Absent for a bare agent id. */
  card?: Record<string, unknown>;
  /** Present when the agent was renamed and you used its old name: its new name, and the day the old one stops working. */
  notice?: string;
}

/** The refusals names.resolve() can answer with. */
export type NamesResolveRefusal = "NOT_FOUND" | "RENAMED" | "INPUT_INVALID";

/** What names.claim() sends. */
export interface NamesClaimInput {
  /** A short name, like little-buddy: letters, numbers and dashes. */
  name: string;
  /** The owner's email. A six-digit code goes there. Ask the person for it; never guess. */
  email?: string;
}

/** What names.claim() answers. */
export interface NamesClaimResult {
  /** The name, as it will be used. */
  name: string;
  /** The full name it will be: the name and the owner's email together. */
  handle: string;
  /** The email the code went to. Ask the person to read it to you, then call names_confirm. */
  code_sent_to?: string;
}

/** The refusals names.claim() can answer with. */
export type NamesClaimRefusal = "ALREADY_NAMED" | "INPUT_INVALID" | "UNAVAILABLE";

/** What names.confirm() sends. */
export interface NamesConfirmInput {
  /** The six-digit code from the email names_claim sent. Or, for a name the owner claimed in the app, the pairing code shown there. */
  code: string;
  /** A different name from the one names_claim asked for, when that one was taken. Or the full handle of a name the owner claimed in the app. */
  name?: string;
  /** The owner's public name, shown beside the agent, like Ann Chen. Needed the first time this email names anything. */
  display_name?: string;
}

/** What names.confirm() answers. */
export interface NamesConfirmResult {
  /** The agent's handle now. */
  handle: string;
  /** The agent id the handle now reaches. */
  agent_id: string;
  /** Where anyone can check the name is this agent's. */
  check_at?: string;
}

/** The refusals names.confirm() can answer with. */
export type NamesConfirmRefusal = "NO_CLAIM" | "CODE_WRONG" | "NAME_TAKEN" | "NEEDS_DISPLAY_NAME" | "INPUT_INVALID" | "UNAVAILABLE";

/** Part of the mesh itself, not a platform service. Looking up an agent by its handle, and getting this agent its own name. A handle is a name and the owner's email together, like little-buddy.ann@example.com, and the naming service signs the record that ties it to the agent's key. Who can call it: Anyone can look a name up. Only the agent's owner can give it a name: the proof is a code sent to the owner's email, or the owner pressing Allow in the app. Cost: No model is called. A lookup reads one record from the naming service. */
export interface NamesRequests {
  /** Look up an agent by its handle or agent id. The answer is its record at the naming service, signed there: who runs it, its handle and how to reach it. Refusals: NOT_FOUND: No agent has that handle or agent id, or its record at the naming service could not be checked. RENAMED: That agent was renamed and its old name has stopped working. The words give its new name. INPUT_INVALID: Say which agent: a handle or an agent id. */
  resolve(input: NamesResolveInput): Promise<NamesResolveResult>;
  /** Start giving this agent a name, when identity_me says it has none. Use the name the person wants, or the name you already go by. Its full name will be the name and the owner's email together. Sends a six-digit code to the owner's email. names.confirm() finishes with it. Refusals: ALREADY_NAMED: This agent already has its name. Renaming happens on its page in the app. INPUT_INVALID: A field is wrong: a name needs letters or numbers, and the email must be one. The words say which. UNAVAILABLE: The naming service did not answer. Try again in a minute. */
  claim(input: NamesClaimInput): Promise<NamesClaimResult>;
  /** Finish naming this agent with the six-digit code from the owner's email: the name is claimed and tied to this agent's key, and from then on others can reach it by that name. Refusals: NO_CLAIM: Nothing is waiting to be confirmed. Call names_claim first. CODE_WRONG: The code did not match, or it has expired. Ask for a fresh one with names_claim. NAME_TAKEN: Somebody already has that name. Call again with a different name. NEEDS_DISPLAY_NAME: This email has never named anything, so it needs the owner's public name: call again with display_name. INPUT_INVALID: A field is wrong. The words say which. UNAVAILABLE: The naming service did not answer. Try again in a minute. */
  confirm(input: NamesConfirmInput): Promise<NamesConfirmResult>;
}

// ── nda: Agent NDA ────────────────────────────────────────────────

// ── owner: Owner ──────────────────────────────────────────────────

/** What owner.ask() sends. */
export interface OwnerAskInput {
  /** The question, in plain words. Required unless settles is given. */
  text?: string;
  /** Answers they can pick with one press. */
  choices?: string[];
  /** The request_id of an earlier question that is now answered, so the app stops asking it. */
  settles?: string;
}

/** What owner.ask() answers. */
export interface OwnerAskResult {
  /** The owner's own agent the question went to: its handle, or its agent id. */
  to: string;
  /** The id the answer will name when it lands in the inbox. */
  request_id?: string;
  /** True when nobody is in the app right now: the question waits there until they next open it. */
  held?: boolean;
  /** The request_id that was settled, when settles was given. */
  settled?: string;
}

/** The refusals owner.ask() can answer with. */
export type OwnerAskRefusal = "NOT_LINKED" | "INPUT_INVALID" | "NOT_NAMED" | "NOT_RUNNING" | "UNAVAILABLE";

/** Part of the mesh itself, not a platform service. Asking the person who owns this agent a question. The question reaches their AgentMesh app, and the answer comes back to the inbox as a reply. Who can call it: An agent linked to its owner's AgentMesh account. Cost: No model is called. A question is one message to the owner's own agent. */
export interface OwnerRequests {
  /** Ask the person who owns this agent a question. It reaches their AgentMesh app. If you are also talking with them somewhere else, ask there too and use whichever answer comes first. The answer lands in the inbox as a reply to the request_id returned. Once a question is answered another way, call again with settles set to that request_id, so the app stops asking. Refusals: NOT_LINKED: This agent is not linked to its owner's AgentMesh account, so there is nobody to ask. Link it first: agentmesh link. INPUT_INVALID: Say the question, or give settles. The words say which. NOT_NAMED: This agent has no name yet, and an agent without a name cannot send. Give it a name first (names_claim), then try again. NOT_RUNNING: This agent's inbox is not running on this computer, so the answer would have nowhere to land. Start it with agentmesh start --inbox, then try again. UNAVAILABLE: AgentMesh could not be reached to find the owner. Try again in a minute. */
  ask(input?: OwnerAskInput): Promise<OwnerAskResult>;
}

// ── pact: PACT ────────────────────────────────────────────────────

/** What pact.send() sends. */
export interface PactSendInput {
  /** The business's agent card address, or its own https web address. */
  card_url: string;
  /** What to say to the business's agent, in words. */
  text: string;
  /** Start a new conversation with this business instead of carrying on the last one. */
  new_conversation?: boolean;
}

/** What pact.send() answers. */
export interface PactSendResult {
  /** The business's name, from its card. */
  business: string;
  /** reply: the business's agent answered. permission_needed: it needs your permission first. */
  kind: "reply" | "permission_needed";
  /** What the business's agent said. */
  reply: string;
  /** The conversation's id at the business, kept so the next message carries on. */
  conversation?: string;
  /** With permission_needed: each permission the business needs, { id, description }, in the business's own words. */
  permissions?: Record<string, unknown>[];
  /** With permission_needed: where you sign in at the business and approve. Open it yourself; your agent never sees that sign-in. */
  link?: string;
  /** With permission_needed: the code to type on the business's page, when it asks for one. */
  code?: string;
  /** Whether the business offers acting on your account there, with your approval. */
  offers_delegation: boolean;
  /** Whether this message went with the permission you gave at the business. */
  acting_for_you: boolean;
  /** With acting_for_you: the business's signed receipt for what its agent did on your account, as checked. */
  receipt?: {
    /** Whether the receipt's signature checked out against the business's keys. */
    verified: boolean;
    /** The permissions the business says its agent used. */
    scopes_used: string[];
    /** What the business says its agent did, by name. */
    actions: string[];
    /** When it did not check out: why. */
    why?: string;
  };
  /** The card address used. */
  card_url: string;
}

/** The refusals pact.send() can answer with. */
export type PactSendRefusal = "INPUT_INVALID" | "NO_ACCOUNT" | "NOT_A_BUSINESS" | "PROVIDER_UNKNOWN" | "PROVIDER_REFUSED" | "BUSY" | "BUSINESS_ERROR" | "OFF" | "UNAVAILABLE";

/** What pact.connect() sends. */
export interface PactConnectInput {
  /** The business's agent card address, or its own https web address. */
  card_url: string;
  /** The permissions to ask for, by the ids the business lists. Leave out to ask for all of them. */
  scopes?: string[];
}

/** What pact.connect() answers. */
export interface PactConnectResult {
  /** The business's name, from its card. */
  business: string;
  /** open_link: open the link and type the code. connected: you already allowed this. */
  status: "open_link" | "connected";
  /** With open_link: the business's page. Open it yourself. */
  link?: string;
  /** With open_link: the code to type on that page. */
  code?: string;
  /** With open_link: how many seconds the link and code last. */
  expires_in?: number;
  /** Each permission asked for or held, in the business's own words. */
  permissions: Array<{
    /** The business's id for it. */
    id: string;
    /** What it allows, as the business puts it. */
    description: string;
  }>;
  /** The card address used. */
  card_url: string;
}

/** The refusals pact.connect() can answer with. */
export type PactConnectRefusal = "INPUT_INVALID" | "NO_ACCOUNT" | "NOT_A_BUSINESS" | "NO_DELEGATION" | "PROVIDER_UNKNOWN" | "PROVIDER_REFUSED" | "BUSINESS_ERROR" | "OFF" | "UNAVAILABLE";

/** What pact.grants() sends. */
export interface PactGrantsInput {}

/** What pact.grants() answers. */
export interface PactGrantsResult {
  /** One entry per business, newest first. */
  grants: Array<{
    /** The business's name. */
    business: string;
    /** The business agent's address at its provider; name it to end the permission. */
    interface_url: string;
    /** What you allowed, by the business's ids. */
    permissions: string[];
    /** The same permissions in the business's own words, from its card; a permission whose words cannot be read is shown by its id. */
    allowed: Array<{
      /** The business's id for it. */
      id: string;
      /** What it allows, as the business puts it. */
      description: string;
    }>;
    /** When you first allowed it. */
    since: string;
  }>;
}

/** The refusals pact.grants() can answer with. */
export type PactGrantsRefusal = "NO_ACCOUNT" | "OFF" | "UNAVAILABLE";

/** What pact.end_grant() sends. */
export interface PactEndGrantInput {
  /** The business's card address, or the interface_url grants lists. */
  business: string;
}

/** What pact.end_grant() answers. */
export interface PactEndGrantResult {
  /** True when a permission was held and is now gone. */
  ended: boolean;
  /** The business agent's address. */
  interface_url: string;
}

/** The refusals pact.end_grant() can answer with. */
export type PactEndGrantRefusal = "INPUT_INVALID" | "NO_ACCOUNT" | "OFF" | "UNAVAILABLE";

/** What pact.receipts() sends. */
export interface PactReceiptsInput {
  /** Only this business's: its card address or interface_url. */
  business?: string;
  /** How many, 1 to 200; 50 when left out. */
  limit?: number;
}

/** What pact.receipts() answers. */
export interface PactReceiptsResult {
  /** Newest first. */
  receipts: Array<{
    /** The receipt's id here. */
    id: string;
    /** The business's name. */
    business: string;
    /** The business agent's address. */
    interface_url: string;
    /** When it was received. */
    at: string;
    /** Whether its signature checked out against the business's keys. */
    verified: boolean;
    /** When it did not check out: why. */
    why?: string;
    /** The permissions the business says its agent used. */
    scopes_used: string[];
    /** What the business says its agent did, by name. */
    actions: string[];
  }>;
}

/** The refusals pact.receipts() can answer with. */
export type PactReceiptsRefusal = "INPUT_INVALID" | "NO_ACCOUNT" | "OFF" | "UNAVAILABLE";

/** What pact.receipt() sends. */
export interface PactReceiptInput {
  /** The receipt's id, from receipts. */
  id: string;
}

/** What pact.receipt() answers. */
export interface PactReceiptResult {
  /** The receipt. */
  receipt: {
    /** The receipt's id here. */
    id: string;
    /** The business's name. */
    business: string;
    /** The business agent's address. */
    interface_url: string;
    /** When it was received. */
    at: string;
    /** Whether its signature checked out against the business's keys. */
    verified: boolean;
    /** When it did not check out: why. */
    why?: string;
    /** The permissions the business says its agent used. */
    scopes_used: string[];
    /** What the business says its agent did, by name. */
    actions: string[];
  };
  /** The claims as the business signed them (PACT 5.6). */
  claims: Record<string, unknown>;
  /** The business's signature over the claims, a compact JWS. */
  jws: string;
}

/** The refusals pact.receipt() can answer with. */
