/** Your agent talks to a business's agent for you, the way PACT 1.0 says: AgentMesh signs each message as the platform your agent runs on, for you, with an id that names nobody and is different at every business's provider. Where a business offers it, you sign in at the business itself and approve what your agent may do on your account there; your agent never sees that sign-in. AgentMesh also hosts businesses' agents for other people's personal agents, through its A2A gateway. Who can call it: Send, connect and the person's own grants and receipts are made for an account: by one of its agents signing with its own key, with the account's API token, or on the hosted connector or in the app, where the person is signed in. The business sees the platform's signature and an id for the person that names nobody. The business requests are made by the owner of the business's agent, for that agent only. The platform requests (which personal-agent platforms AgentMesh's gateway accepts) take an operator key with the pact scope. Cost: No model is called by PACT itself. A send reads the business's card (kept five minutes), signs one token and makes one request to the business's provider; whatever the business's agent does is the business's. */
export interface PactRequests {
  /** Send a message to a business's agent and read its answer, as your agent, signed by AgentMesh for you. Give the business's agent card address, or its own web address, which serves the card. The conversation with that business carries on from the last message unless you ask for a new one. When the business needs your permission for something, the answer says what and gives a link where you sign in at the business itself, and a code. An agent shows the person the link and the code and asks them to open it themselves; it never opens, fetches or frames that page. After they allow it, send again. Refusals: INPUT_INVALID: A field is wrong: an address that is not https, or empty text. NO_ACCOUNT: There is no account to act for: sign the request with one of your agents, or send your account's token. NOT_A_BUSINESS: There is no PACT business at that address: no card, a card that is not JSON, or a card with no A2A 1.0 HTTP+JSON interface. PROVIDER_UNKNOWN: AgentMesh is not registered with the provider that hosts this business, so it cannot sign for you there. PROVIDER_REFUSED: The business's provider did not accept AgentMesh's signature: AgentMesh is not registered there yet, or its registration is off. BUSY: The business's provider asked to wait before the next message. The words say how long. BUSINESS_ERROR: The business's agent refused the message. The words carry its reason. OFF: Acting at businesses is not set up on this system yet. UNAVAILABLE: The business's card or its provider could not be reached, or this system's records are not available just now. */
  send(input: PactSendInput): Promise<PactSendResult>;
  /** Ask a business for permission for your agent to act on your account there, the way PACT 1.0 says. You get a link to open yourself and a code to type: you sign in at the business itself and choose what to allow, and your agent never sees that sign-in. Name the permissions, or leave them out to ask for every one the business offers. An agent shows the person the link and the code and never opens that page itself. Ask again after you approve to see that it is done. Refusals: INPUT_INVALID: A field is wrong: an address that is not https, or a permission the business does not offer. NO_ACCOUNT: There is no account to act for: sign the request with one of your agents, or send your account's token. NOT_A_BUSINESS: There is no PACT business at that address. NO_DELEGATION: The business does not offer acting on your account, or this system cannot keep its permission safely yet. PROVIDER_UNKNOWN: AgentMesh is not registered with the provider that hosts this business. PROVIDER_REFUSED: The business's provider did not accept AgentMesh's signature. BUSINESS_ERROR: The business refused the request for permission. The words carry its reason. OFF: Acting at businesses is not set up on this system yet. UNAVAILABLE: The business's card, provider or sign-in service could not be reached. */
  connect(input: PactConnectInput): Promise<PactConnectResult>;
  /** The businesses where you allowed your agent to act on your account, with what each permission allows and since when. Refusals: NO_ACCOUNT: There is no account to answer for. OFF: Acting at businesses is not set up on this system yet. UNAVAILABLE: This system's records are not available just now. */
  grants(input?: PactGrantsInput): Promise<PactGrantsResult>;
  /** Your agent stops acting on your account at a business: what it held is thrown away at once, and it asks you again before it acts there. Name the business by its card address or the address grants lists. Refusals: INPUT_INVALID: That is not an address. NO_ACCOUNT: There is no account to answer for. OFF: Acting at businesses is not set up on this system yet. UNAVAILABLE: This system's records are not available just now. */
  end_grant(input: PactEndGrantInput): Promise<PactEndGrantResult>;
  /** The receipts businesses signed for what their agents did on your account, newest first, each marked whether its signature checked out. Refusals: INPUT_INVALID: A field is out of shape. NO_ACCOUNT: There is no account to answer for. OFF: Acting at businesses is not set up on this system yet. UNAVAILABLE: This system's records are not available just now. */
  receipts(input?: PactReceiptsInput): Promise<PactReceiptsResult>;
  /** One receipt as the business signed it: its claims and the signature itself, so anyone can check it again against the business's keys. Refusals: INPUT_INVALID: id is missing. NO_ACCOUNT: There is no account to answer for. NOT_FOUND: No receipt of yours has that id. OFF: Acting at businesses is not set up on this system yet. UNAVAILABLE: This system's records are not available just now. */
  receipt(input: PactReceiptInput): Promise<PactReceiptResult>;
  /** For one of your own agents that serves a business: whether people's own agents can act on their accounts there, the permissions it offers (declared with its offerings in its package spec), and the sign-in connected for it, never its secret. Refusals: INPUT_INVALID: of_agent is missing. NO_ACCOUNT: There is no account to answer for. NOT_YOURS: That is not one of your account's agents. UNAVAILABLE: The A2A gateway did not answer just now. */
  business(input: PactBusinessInput): Promise<PactBusinessResult>;
  /** Connect your business's own sign-in to one of your agents, so a person can sign in at your business and allow their agent to act for them there. Register the redirect_uri that business names with your identity provider first, then give its OpenID Connect issuer, the client id and the client secret. The secret is kept like a private key and is never shown again. Refusals: INPUT_INVALID: A field is missing, the issuer is not https, or its discovery document could not be read. The words say which. NO_ACCOUNT: There is no account to answer for. NOT_YOURS: That is not one of your account's agents. UNAVAILABLE: The A2A gateway did not answer just now. */
  business_login(input: PactBusinessLoginInput): Promise<PactBusinessLoginResult>;
  /** Disconnect the sign-in from one of your agents. People's own agents can no longer ask to act on their accounts there; permissions already given stop working when their tokens next renew. Refusals: INPUT_INVALID: of_agent is missing. NO_ACCOUNT: There is no account to answer for. NOT_YOURS: That is not one of your account's agents. UNAVAILABLE: The A2A gateway did not answer just now. */
  business_logout(input: PactBusinessLogoutInput): Promise<PactBusinessLogoutResult>;
  /** The permissions people gave their own agents at one of your agents: the person's id at your business, which personal-agent platform, what they allowed, since when, and whether it has ended. No token is ever shown. Refusals: INPUT_INVALID: of_agent is missing. NO_ACCOUNT: There is no account to answer for. NOT_YOURS: That is not one of your account's agents. UNAVAILABLE: The A2A gateway did not answer just now. */
  business_grants(input: PactBusinessGrantsInput): Promise<PactBusinessGrantsResult>;
  /** End one permission at one of your agents at once: the token the person's agent holds is refused on its next use. Refusals: INPUT_INVALID: A field is missing. NO_ACCOUNT: There is no account to answer for. NOT_YOURS: That is not one of your account's agents, or the permission is not at it. UNAVAILABLE: The A2A gateway did not answer just now. */
  business_end_grant(input: PactBusinessEndGrantInput): Promise<PactBusinessEndGrantResult>;
  /** The personal-agent platforms AgentMesh's A2A gateway accepts on this system, and the audience it assigns them all. This system's own personal agent is accepted without a record. Refusals: NOT_OPERATOR: Only an operator may see this, with an operator key carrying the pact scope. UNAVAILABLE: The A2A gateway did not answer just now. */
  platforms(input?: PactPlatformsInput): Promise<PactPlatformsResult>;
  /** List a personal-agent platform with AgentMesh's A2A gateway: its issuer, matched exactly, and where its public keys are. Tell the platform the audience this answers with. Refusals: INPUT_INVALID: A field is out of shape, or the platform is listed already. The words say which. NOT_OPERATOR: Only an operator may do this, with an operator key carrying the pact scope. UNAVAILABLE: The A2A gateway did not answer just now. */
  platform_add(input: PactPlatformAddInput): Promise<PactPlatformAddResult>;
  /** Turn a listed platform off or on, rename it, or point it at new keys. Refusals: INPUT_INVALID: A field is out of shape. NOT_FOUND: No platform has that id. NOT_OPERATOR: Only an operator may do this, with an operator key carrying the pact scope. UNAVAILABLE: The A2A gateway did not answer just now. */
  platform_set(input: PactPlatformSetInput): Promise<PactPlatformSetResult>;
  /** Take a platform off the list: its tokens are refused at once. Refusals: INPUT_INVALID: id is missing. NOT_FOUND: No platform has that id. NOT_OPERATOR: Only an operator may do this, with an operator key carrying the pact scope. UNAVAILABLE: The A2A gateway did not answer just now. */
  platform_remove(input: PactPlatformRemoveInput): Promise<PactPlatformRemoveResult>;
}

/** PACT, through the platform's service door. */
export class PactService implements PactRequests {
  constructor(private readonly caller: ServiceCaller) {}
  send(input: PactSendInput): Promise<PactSendResult> {
    return this.caller.call("pact.send", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactSendResult>;
  }
  connect(input: PactConnectInput): Promise<PactConnectResult> {
    return this.caller.call("pact.connect", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactConnectResult>;
  }
  grants(input?: PactGrantsInput): Promise<PactGrantsResult> {
    return this.caller.call("pact.grants", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactGrantsResult>;
  }
  end_grant(input: PactEndGrantInput): Promise<PactEndGrantResult> {
    return this.caller.call("pact.end_grant", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactEndGrantResult>;
  }
  receipts(input?: PactReceiptsInput): Promise<PactReceiptsResult> {
    return this.caller.call("pact.receipts", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactReceiptsResult>;
  }
  receipt(input: PactReceiptInput): Promise<PactReceiptResult> {
    return this.caller.call("pact.receipt", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactReceiptResult>;
  }
  business(input: PactBusinessInput): Promise<PactBusinessResult> {
    return this.caller.call("pact.business", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactBusinessResult>;
  }
  business_login(input: PactBusinessLoginInput): Promise<PactBusinessLoginResult> {
    return this.caller.call("pact.business_login", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactBusinessLoginResult>;
  }
  business_logout(input: PactBusinessLogoutInput): Promise<PactBusinessLogoutResult> {
    return this.caller.call("pact.business_logout", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactBusinessLogoutResult>;
  }
  business_grants(input: PactBusinessGrantsInput): Promise<PactBusinessGrantsResult> {
    return this.caller.call("pact.business_grants", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactBusinessGrantsResult>;
  }
  business_end_grant(input: PactBusinessEndGrantInput): Promise<PactBusinessEndGrantResult> {
    return this.caller.call("pact.business_end_grant", (input ?? {}) as unknown as Record<string, unknown>, "signature") as Promise<PactBusinessEndGrantResult>;
  }
  platforms(input?: PactPlatformsInput): Promise<PactPlatformsResult> {
    return this.caller.call("pact.platforms", (input ?? {}) as unknown as Record<string, unknown>, "operator") as Promise<PactPlatformsResult>;
  }
  platform_add(input: PactPlatformAddInput): Promise<PactPlatformAddResult> {
    return this.caller.call("pact.platform_add", (input ?? {}) as unknown as Record<string, unknown>, "operator") as Promise<PactPlatformAddResult>;
  }
  platform_set(input: PactPlatformSetInput): Promise<PactPlatformSetResult> {
    return this.caller.call("pact.platform_set", (input ?? {}) as unknown as Record<string, unknown>, "operator") as Promise<PactPlatformSetResult>;
  }
  platform_remove(input: PactPlatformRemoveInput): Promise<PactPlatformRemoveResult> {
    return this.caller.call("pact.platform_remove", (input ?? {}) as unknown as Record<string, unknown>, "operator") as Promise<PactPlatformRemoveResult>;
  }
}

// ── portfolio: Portfolio ──────────────────────────────────────────

/** What portfolio.read() sends. */
export interface PortfolioReadInput {
  /** One line, by its ln_ id. The whole record when left out. */
  line_id?: string;
}

/** What portfolio.read() answers. */
export interface PortfolioReadResult {
  /** The whole record, when no line was named: its lines and when it changed. */
  portfolio?: Record<string, unknown>;
  /** The line, when one was named. */
  line?: Record<string, unknown>;
}

/** The refusals portfolio.read() can answer with. */
export type PortfolioReadRefusal = "INPUT_INVALID" | "NO_ACCOUNT" | "NOT_OWNER" | "NOT_FOUND" | "UNAVAILABLE";

/** What portfolio.draft() sends. */
export interface PortfolioDraftInput {
  /** The line to update. A new line when left out. */
  line_id?: string;
  /** Where the job came from: human (people told you), market (you looked it up) or heuristic (you worked it out yourself). */
  provenance: "human" | "market" | "heuristic";
  /** One sentence, written with the person: what the job is. */
  summary?: string;
  /** A published role: its offering, where it is published (registry), and its version if wanted. Give this or profile, not both. */
  role?: Record<string, unknown>;
  /** The job described here instead of by a published role: its scope, the access it needs, what it refuses, and its documents. Give this or role, not both. */
  profile?: Record<string, unknown>;
  /** Limits on the job: how many agents, the budget, how careful the agent must be, who can approve its actions, how often it is reviewed (its tier), what to fall back to, and when the term ends. */
  constraints?: Record<string, unknown>;
  /** The line's dependencies, replacing what is stored. portfolio_depend changes one at a time. */
  dependencies?: Record<string, unknown>[];
}

/** What portfolio.draft() answers. */
export interface PortfolioDraftResult {
  /** The line as stored. */
  line: Record<string, unknown>;
  /** Lines that depend on this one, when it was an update. */
  downstream?: unknown[];
  /** What happens next, for a new line. */
  note?: string;
}

/** The refusals portfolio.draft() can answer with. */
export type PortfolioDraftRefusal = "INPUT_INVALID" | "NO_ACCOUNT" | "NOT_OWNER" | "NOT_FOUND" | "UNAVAILABLE";

/** What portfolio.depend() sends. */
export interface PortfolioDependInput {
  /** The line that depends. */
  line_id: string;
  /** Add the dependency or remove it. */
  action: "add" | "remove";
  /** What it depends on: {line: ln_ id} or {human: a role's name}. */
  consumes: Record<string, unknown>;
  /** What the other side hands over, in plain words. */
  delivers: string;
}

/** What portfolio.depend() answers. */
export interface PortfolioDependResult {
  /** The line's id. */
  line: string;
  /** Its dependencies now. */
  dependencies: Record<string, unknown>[];
  /** What it consumes, and every line that now consumes the same. */
  seam: Record<string, unknown>;
}

/** The refusals portfolio.depend() can answer with. */
export type PortfolioDependRefusal = "INPUT_INVALID" | "DUPLICATE" | "NO_ACCOUNT" | "NOT_OWNER" | "NOT_FOUND" | "UNAVAILABLE";

/** What portfolio.transition() sends. */
