/** Transformation projects on AgentMesh transform: the projects a person may open, and on each one its goals and phases, the processes it adopted, the questions still open on them, and which of the company's systems answers each system role. Every request reads; to change a project, send the transform helper the act in a message. Who can call it: People on a transformation project: the account the caller acts for, on the projects that account may open, whether it runs the project or only reads it. Through the adapter and the SDKs that is the account holding the agent that signs; on the hosted connector, the person signed in. Cost: Free, and no model is called. Each request reads the project's records; idle, the service costs nothing. */
export interface TransformRequests {
  /** The transformation projects you may open: each one's id, name, who it is for, whether it is your own company's, and whether you run it (can change it) or only read it. Call this first: the other requests take a project's id. Refusals: NO_ACCOUNT: There is no account to list projects for: sign the request with an agent that belongs to an account. UNAVAILABLE: Transformation projects are not available on this system just now. Try again in a minute. */
  projects(input?: TransformProjectsInput): Promise<TransformProjectsResult>;
  /** What one project is: who it is for, its goals, phases and workstreams, your role on it, and how much is adopted, still open, waiting on people and planned. Refusals: INPUT_INVALID: The project's id is missing. NO_ACCOUNT: There is no account to read the project as: sign the request with an agent that belongs to an account. NOT_FOUND: No such project, or not one you may open. transform_projects lists yours. UNAVAILABLE: Transformation projects are not available on this system just now. Try again in a minute. */
  summary(input: TransformSummaryInput): Promise<TransformSummaryResult>;
  /** The processes a project adopted, each with its id, name, department, owner, how many of its questions are open, and who is on it. Refusals: INPUT_INVALID: The project's id is missing. NO_ACCOUNT: There is no account to read the project as: sign the request with an agent that belongs to an account. NOT_FOUND: No such project, or not one you may open. transform_projects lists yours. UNAVAILABLE: Transformation projects are not available on this system just now. Try again in a minute. */
  processes(input: TransformProcessesInput): Promise<TransformProcessesResult>;
  /** One adopted process in full: its steps and who holds each, its questions (open and answered, with their keys), its people and the systems it names. Refusals: INPUT_INVALID: The project's id or the process is missing. NO_ACCOUNT: There is no account to read the project as: sign the request with an agent that belongs to an account. NOT_FOUND: No such project you may open, or no such process on it. transform_processes lists them. UNAVAILABLE: Transformation projects are not available on this system just now. Try again in a minute. */
  process(input: TransformProcessInput): Promise<TransformProcessResult>;
  /** Every question still open across a project's processes, with the process, the question's key and its words. Answering one is a change: send it to the transform helper. Refusals: INPUT_INVALID: The project's id is missing. NO_ACCOUNT: There is no account to read the project as: sign the request with an agent that belongs to an account. NOT_FOUND: No such project, or not one you may open. transform_projects lists yours. UNAVAILABLE: Transformation projects are not available on this system just now. Try again in a minute. */
  blanks(input: TransformBlanksInput): Promise<TransformBlanksResult>;
  /** A project's systems dictionary: which of the company's systems answers each system role its processes name, how agents reach it, and where records live. Refusals: INPUT_INVALID: The project's id is missing. NO_ACCOUNT: There is no account to read the project as: sign the request with an agent that belongs to an account. NOT_FOUND: No such project, or not one you may open. transform_projects lists yours. UNAVAILABLE: Transformation projects, or their systems, are not available on this system just now. */
  systems(input: TransformSystemsInput): Promise<TransformSystemsResult>;
  /** Search the catalog of reference processes by words in the title, department or goal, for a project. Each comes with the key to adopt it by; adopting is a change, so send it to the transform helper. Refusals: INPUT_INVALID: The project's id or the words are missing. NO_ACCOUNT: There is no account to search for: sign the request with an agent that belongs to an account. NOT_FOUND: No such project, or not one you may open. transform_projects lists yours. UNAVAILABLE: Transformation projects are not available on this system just now. Try again in a minute. */
  find(input: TransformFindInput): Promise<TransformFindResult>;
}

